import json,hashlib
from pathlib import Path

def run(c,root,args):
 c.group='library-headers';pub=root/'labs/foundations/library_depth';private=root/'assessor/legacy_library';source=private/'headers.c'
 for cc in ('gcc','clang'):
  for name,flags in [('debug',['-O0']),('release',['-O2']),('sanitize',['-O1','-fsanitize=address,undefined','-fno-pie','-no-pie'])]:
   exe=c.root/(cc+'-'+name+'-headers');c.run([cc,'-std=c17','-Wall','-Wextra','-Werror','-Wformat=2',*flags,'-I'+str(pub),pub/'headers_tests.c',source,'-o',exe]);c.run([exe],contains='HEADERS-PASS:')
  matrix=json.loads(c.run(['python3',private/'header_probe.py',cc,c.root/(cc+'-headers')]));c.require(matrix['count']==30 and len({(r['edition'],r['header']) for r in matrix['cells']})==30,'actual header acceptance matrix '+cc,matrix);c.write(cc+'-header-matrix.json',json.dumps(matrix,indent=2))
  # Function-address declarations retain references even if no call is executed.
  signatures={'memcpy':('string.h','void *(*facility)(void *,const void *,size_t)=memcpy;'), 'strtol':('stdlib.h','long (*facility)(const char *,char **,int)=strtol;'), 'snprintf':('stdio.h','int (*facility)(char *,size_t,const char *,...)=snprintf;'), 'clock':('time.h','clock_t (*facility)(void)=clock;'), 'signal':('signal.h','void (*(*facility)(int,void (*)(int)))(int)=signal;'), 'qsort':('stdlib.h','void (*facility)(void *,size_t,size_t,int (*)(const void *,const void *))=qsort;')}
  for name,(header,body) in signatures.items():
   tu=c.write('headers/'+name+'.c','#include <'+header+'>\n'+body+'\n');obj=c.root/(cc+'-'+name+'.o')
   dep=c.root/(cc+'-'+name+'.d');c.run([cc,'-std=c17','-pedantic-errors','-Wall','-Wextra','-Werror','-ffreestanding','-fno-builtin','-MD','-MF',dep,'-c',tu,'-o',obj]);symbols=c.run(['nm','-u',obj]);allowed={name,'__sysv_signal'} if name=='signal' else {name};actual={line.split()[-1] for line in symbols.splitlines()};c.require(len(actual)==1 and actual<=allowed,'independent declaration retains external definition '+cc+' '+name,symbols)
   dependencies=dep.read_text().replace('\\\n',' ').split(':',1)[1].split();c.require(bool(dependencies),'facility dependency identities '+cc+' '+name,{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in dependencies})
   if name=='signal':expanded=c.run([cc,'-std=c17','-E',tu]);c.require('__sysv_signal' in expanded,'actual glibc signal ABI redirection inspected '+cc);c.write(cc+'-signal-preprocessed.c',expanded)
   c.run([cc,'-nostdlib','-no-pie','-Wl,-e,facility',obj,'-o',c.root/(cc+'-'+name+'-missing')],expected='nonzero',contains=next(iter(actual)))
  missing=c.write('headers/only-stdlib.c','#include <stdlib.h>\nvoid *(*copy)(void*,const void*,size_t)=memcpy;\n');c.run([cc,'-std=c17','-Werror','-c',missing,'-o',c.root/(cc+'-missing.o')],expected='nonzero',contains='memcpy')
 # Actual i386 hosted ABI: uintmax_t64 and size_t32, explicit private loader.
 sysroot=root/'build/posix-io-toolchain/sysroot';libs=sysroot/'usr/lib32';loader=libs/'ld-linux.so.2';gccdir=sysroot/'usr/lib/gcc/x86_64-linux-gnu/15/32';target=['-m32','--sysroot='+str(sysroot),'-isystem',str(sysroot/'usr/include/x86_64-linux-gnu'),'-B'+str(gccdir)+'/','-L'+str(libs),'-Wl,--dynamic-linker='+str(loader)]
 for path in (loader,libs/'libc.so.6',gccdir/'crtbeginS.o'):c.require(path.is_file(),'required actual i386 dependency '+path.name,dict(path=str(path),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
 for name,flag in [('i386-headers',None),('headers-narrow','LH_MUTANT_NARROW')]:
  exe=c.root/name;c.run(['gcc','-std=c17','-O2','-Wall','-Wextra','-Werror','-Wformat=2',*target,*(['-D'+flag] if flag else []),'-I'+str(pub),pub/'headers_tests.c',source,'-o',exe]);text=c.run([loader,'--library-path',libs,exe],expected=1 if flag else 0,contains='HEADERS-CHECK:' if flag else 'HEADERS-PASS:')
  if not flag:c.require('size_bytes=4' in text and 'uintmax_bytes=8' in text,'actual wider intermediate executed',text)
 for name,flag,selected in [('headers-zero','LH_MUTANT_ZERO',source),('headers-capability','LH_MUTANT_HEADER',source),('headers-learner','UNSOLVED',pub/'headers.c')]:
  exe=c.root/name;c.run(['gcc','-std=c17','-O2','-D'+flag,'-I'+str(pub),pub/'headers_tests.c',selected,'-o',exe]);c.run([exe],expected=1,contains='HEADERS-CHECK:')
 # Real AVR frontend and actual avr-libc2.2.1 headers, not a typedef simulation.
 avr=Path('/home/frede/cmastery-library-tools/sysroot/usr/lib/avr/include');c.require((avr/'stdint.h').is_file(),'explicit AVR libc headers available')
 common=['clang','--target=avr','-mmcu=atmega328p','-isystem',str(avr),'-std=c17','-Wall','-Wextra','-Werror','-Wformat=2']
 text='#include <stdint.h>\n#include <stddef.h>\n#include <inttypes.h>\n#include <stdio.h>\n_Static_assert(sizeof(int)==2,"int16");\n_Static_assert(_Generic((uint32_t)0,unsigned long:1,default:0),"uint32 ulong");\n_Static_assert(sizeof(uintmax_t)>sizeof(size_t),"wider");\nint formats(char *p,size_t n,uint32_t x){return snprintf(p,n,"%" PRIu32,x);}\n'
 good=c.write('headers/avr.c',text);bad=c.write('headers/avr-wrong.c',text.replace('"%" PRIu32','"%u"'))
 c.run([*common,'-fsyntax-only',good]);c.run([*common,'-fsyntax-only',bad],expected='nonzero',contains='format')
 dep=c.root/'avr.d';c.run([*common,'-MD','-MF',dep,'-S','-emit-llvm',good,'-o',c.root/'avr.ll']);dependencies=dep.read_text().replace('\\\n',' ').split(':',1)[1].split();c.require(bool(dependencies),'AVR actual dependency identities',{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in dependencies})
 # Strict core plus original entry: final linked image, no implicit helpers.
 entry=c.write('headers/entry.c','#include "headers.h"\nvolatile size_t result;void _start(void){size_t n=0;if(lh_size((const unsigned char*)"123",3,&n)==LH_OK)result=n;for(;;){}}\n');image=c.root/'headers-strict.elf'
 c.run(['gcc','-std=c17','-O2','-ffreestanding','-fno-builtin','-fno-stack-protector','-nostdlib','-static','-I'+str(pub),entry,source,'-Wl,-Map='+str(c.root/'headers-strict.map'),'-o',image]);imports=c.run(['nm','-u',image]);c.require(not imports.strip(),'strict parser final image has empty runtime closure',imports);c.run(['objdump','-dr',image])
 # Header-only facilities are compile-time, unlike retained malloc/snprintf.
 constants=c.write('headers/constants.c','#include <stddef.h>\n#include <stdint.h>\nstruct pair{char tag;long value;};\nsize_t offset(void){return offsetof(struct pair,value)+sizeof(size_t)+(SIZE_MAX>0);}\n')
 calls=c.write('headers/calls.c','#include <stdlib.h>\n#include <stdio.h>\nint library_path(int use){if(!use)return 0;char *p=malloc(32);if(!p)return 1;int n=snprintf(p,32,"%d",use);free(p);return n<0;}\n')
 main=c.write('headers/main.c','int library_path(int);int main(void){return library_path(0);}\n')
 for cc in ('gcc','clang'):
  obj=c.root/(cc+'-constants.o');c.run([cc,'-std=c17','-O2','-ffreestanding','-fno-builtin','-c',constants,'-o',obj]);c.require(not c.run(['nm','-u',obj]).strip(),'header constants require no definitions '+cc)
  obj=c.root/(cc+'-calls.o');c.run([cc,'-std=c17','-O0','-fno-builtin','-c',calls,'-o',obj]);symbols=c.run(['nm','-u',obj]);c.require({'malloc','snprintf','free'}<={line.split()[-1] for line in symbols.splitlines()},'actual call relocations '+cc,symbols);c.run(['objdump','-dr',obj]);exe=c.root/(cc+'-calls');c.run([cc,main,obj,'-Wl,-Map='+str(c.root/(cc+'-calls.map')),'-o',exe]);c.run([exe]);c.run(['nm','-D',exe])
 # GCC LTO crosses translation units; success is call elimination, not provisioning.
 exe=c.root/'headers-lto';c.run(['gcc','-std=c17','-O2','-flto',main,calls,'-Wl,-Map='+str(c.root/'headers-lto.map'),'-o',exe]);c.run([exe]);dynamic=c.run(['nm','-D',exe]);c.require('malloc' not in dynamic and 'snprintf' not in dynamic,'LTO removes unreachable library path',dynamic)
 # Extension classification is tested with exact declarations and core rejection.
 posix=c.write('headers/posix.c','#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <string.h>\n#include <sys/types.h>\nssize_t (*line)(char**,size_t*,FILE*)=getline;char *(*token)(char*,const char*,char**)=strtok_r;int main(void){return 0;}\n');exe=c.root/'headers-posix';c.run(['gcc','-std=c17','-Wall','-Wextra','-Werror',posix,'-o',exe]);c.run([exe])
 core=c.write('headers/no-posix.c',posix.read_text().replace('#define _POSIX_C_SOURCE 200809L\n',''));c.run(['gcc','-std=c17','-Werror','-c',core,'-o',c.root/'headers-no-posix.o'],expected='nonzero',contains='getline')
 annex=c.write('headers/annex.c','#define __STDC_WANT_LIB_EXT1__ 1\n#include <string.h>\n#ifndef __STDC_LIB_EXT1__\n#error ANNEX_K_NOT_PROVIDED\n#endif\n');c.run(['gcc','-std=c17','-c',annex,'-o',c.root/'headers-annex.o'],expected='nonzero',contains='ANNEX_K_NOT_PROVIDED')
 attribute=c.write('headers/attribute.c','static int unused(void) __attribute__((unused));static int unused(void){return 1;}int main(void){return 0;}\n');c.run(['gcc','-std=c17','-Wall','-Wextra','-Werror',attribute,'-o',c.root/'headers-attribute'])
 for key,ordinary,changed in [('01.a','Six independent function-address TUs use exact owning headers; stdlib-only memcpy is rejected; external definitions remain visible','All six provided headers also translate in freestanding mode but nostdlib links reject missing definitions; separate original parser final image has no imports'),('01.b','All30 header/edition cells observed separately under GCC/Clang; source matrix distinguishes C99TC3/C11/C23 drafts from C90/C17 exact-text gaps','All16 capability combinations reject old-mode/header-only/no-threads/link-failure as C11-thread support; fallback requires explicit serialized contract'),('01.c','ISO core/optional AnnexK/POSIX/GNU classifications have distinct probes; current hosted AnnexK unavailable','Same original counted parser executes without AnnexK and links a strict no-FILE/no-runtime image; POSIX hidden declarations reject in core mode'),('02.a','Actual size/ptrdiff/uint32/uintmax/CHAR_BIT ledger uses PRI/SCN and correct pointer formats across six profiles','Actual AVR int16 frontend with avr-libc verifies uint32 unsigned long, correct PRI type and wrong %u diagnostic; no AVR execution inferred'),('02.b','Full decimal lengths accumulate wide and reject range before publishing; fixed-width maximum roundtrips use actual PRI/SCN','Actual i386 execution with uintmax64,size32 rejects SIZE_MAX+1 and semantic early-narrowing mutant; AVR separately checks unsigned-long typedef'),('02.c','sizeof/offsetof/limits object needs no definitions; actual malloc/snprintf/free relocations and final maps retained','Cross-TU LTO removes unused library path; strict parser final link audited independently and cannot establish availability of absent hosted facilities')]:c.observe('T12.'+key,ordinary,['library-headers']);c.observe('T12.'+key,changed,['library-headers'],True)
